import math
def is_pronic(number):
    if number==0:
        return True
    x=int(math.sqrt(number))
    return x*(x+1)==number
def f_pronic_numbers(number):
    char=str(number)
    length=len(char)
    # pronic_number=[]
    for i in range(length):
        for j in range(i+1,length+1):
            if is_pronic(int(char[i:j])) and (char[i:j]==str(int(char[i:j]))):
                print(char[i:j],end=&quot; &quot;)

