def bit_string(n):
    list = []
    if n == 0:
        return list
    else:
        list.append(0)
        list.append(1)
        i = 1
        while i &lt; n:
            temp_list = []
            for num in list:
                num = str(num)
                temp_list.append(num+'1')
                temp_list.append(num+'0')
                list = temp_list
            i = i + 1
        for k in range(2,n+1):
            for num in list:
                if '0'*k in num:
                    list.remove(num)
    list = set(list)
    return list

print(bit_string(4))

class ApiLoggerConfig(BaseModel):
    &quot;&quot;&quot;Logging configuration to be set for all APIs.&quot;&quot;&quot;

    formatters: dict = {
        &quot;uvicorn&quot;: {
            &quot;()&quot;: &quot;uvicorn.logging.DefaultFormatter&quot;,
            &quot;fmt&quot;: &quot;%(levelprefix)s %(asctime)s  %(name)s:%(lineno)d: %(message)s&quot;,
            &quot;datefmt&quot;: DATEFMT,
        },
        &quot;access&quot;: {
            &quot;()&quot;: &quot;uvicorn.logging.AccessFormatter&quot;,
            &quot;fmt&quot;: '%(levelprefix)s %(asctime)s  %(name)s: %(client_addr)s - &quot;%(request_line)s&quot; %(status_code)s',
            &quot;datefmt&quot;: DATEFMT,
        },
    }

    handlers: dict = {
        &quot;uvicorn&quot;: {
            &quot;formatter&quot;: &quot;uvicorn&quot;,
            &quot;class&quot;: &quot;logging.StreamHandler&quot;,
            &quot;stream&quot;: &quot;ext://sys.stderr&quot;,
        },
        &quot;access&quot;: {
            &quot;formatter&quot;: &quot;access&quot;,
            &quot;class&quot;: &quot;logging.StreamHandler&quot;,
            &quot;stream&quot;: &quot;ext://sys.stdout&quot;,
        },
    }

    loggers: dict = {
        &quot;uvicorn&quot;: {&quot;handlers&quot;: [&quot;uvicorn&quot;], &quot;level&quot;: LOG_LEVEL, &quot;propagate&quot;: False},
        &quot;uvicorn.error&quot;: {&quot;level&quot;: LOG_LEVEL},
        &quot;uvicorn.access&quot;: {
            &quot;handlers&quot;: [&quot;access&quot;],
            &quot;level&quot;: LOG_LEVEL,
            &quot;propagate&quot;: False,
        },
    }
    def add_logger(
        self,
        name: str,
        handler: str = &quot;default&quot;,
        propagate: bool = False,
    ):

        self.loggers[name] = {
            &quot;handlers&quot;: [handler],
            &quot;level&quot;: self.LOG_LEVEL,
            &quot;propagate&quot;: propagate,
        }


def _setup_logging(app: FastAPI):
    LOGGING_CONFIG = ApiLoggerConfig()
    # Load Azure logging config for cloud setup only
    if os.getenv(&quot;APPLICATIONINSIGHTS_CONNECTION_STRING&quot;):
        from azure.monitor.opentelemetry import configure_azure_monitor
        from opentelemetry.instrumentation.fastapi import FastAPIInstrumentor

        # set metrics extractor to root
        configure_azure_monitor()
        FastAPIInstrumentor.instrument_app(app)
    LOGGING_CONFIG.add_logger(__name__)
    dictConfig(LOGGING_CONFIG)
    return logging.getLogger(__name__)


app = FastAPI()

logger = _setup_logging(app)

