# Mobius server info
BASE_URL = &quot;http://127.0.0.1:7579/Mobius&quot;
HEADERS = {
    &quot;X-M2M-Origin&quot;: &quot;SOrigin&quot;,  # Mobius basic Origin
    &quot;Content-Type&quot;: &quot;application/json&quot;
}

def create_ae(ae_name):
    &quot;&quot;&quot;Application Entity (AE) creation in Mobius&quot;&quot;&quot;
    url = BASE_URL
    payload = {
        &quot;m2m:ae&quot;: {
            &quot;rn&quot;: ae_name,
            &quot;api&quot;: &quot;0.2.481.2.0001.001.000111&quot;,
            &quot;rr&quot;: True,
            &quot;poa&quot;: [&quot;http://203.254.173.104:9727&quot;]
        }
    }
    response = requests.post(url, headers={**HEADERS, &quot;ty&quot;: &quot;2&quot;}, json=payload)
    if response.status_code in [200, 201]:
        print(f&quot;AE creation success: {ae_name}&quot;)
    else:
        print(f&quot;AE creation failed: {response.status_code}, {response.text}&quot;)

def create_container(ae_name, container_name):
    &quot;&quot;&quot;Container Creation in Mobius&quot;&quot;&quot;
    url = f&quot;{BASE_URL}/{ae_name}&quot;
    payload = {
        &quot;m2m:cnt&quot;: {
            &quot;rn&quot;: container_name
        }
    }
    response = requests.post(url, headers={**HEADERS, &quot;ty&quot;: &quot;3&quot;}, json=payload)
    if response.status_code in [200, 201]:
        print(f&quot;Container creation success: {container_name}&quot;)
    else:
        print(f&quot;Container creation failed: {response.status_code}, {response.text}&quot;)

def send_data(ae_name, container_name, data):
    &quot;&quot;&quot;(ContentInstance) transmission in Mobius&quot;&quot;&quot;
    url = f&quot;{BASE_URL}/{ae_name}/{container_name}&quot;
    payload = {
        &quot;m2m:cin&quot;: {
            &quot;con&quot;: data  # send data 
        }
    }
    response = requests.post(url, headers={**HEADERS, &quot;ty&quot;: &quot;4&quot;}, json=payload)
    if response.status_code in [200, 201]:
        print(f&quot;data transmission success: {data}&quot;)
    else:
        print(f&quot;data transmission failed: {response.status_code}, {response.text}&quot;)

# example
if __name__ == &quot;__main__&quot;:
    AE_NAME = &quot;myApp&quot;
    CONTAINER_NAME = &quot;myContainer&quot;
    DATA = &quot;Hello, Mobius from Python!&quot;

    # Step 1: AE creation
    create_ae(AE_NAME)

    # Step 2: Container creation
    create_container(AE_NAME, CONTAINER_NAME)

    # Step 3: data transmission
    send_data(AE_NAME, CONTAINER_NAME, DATA)

