import concurrent.futures
import urllib.request

URLS = ['http://www.foxnews.com/',
        'http://www.cnn.com/',
        'http://europe.wsj.com/',
        'http://www.bbc.co.uk/',
        'http://some-made-up-domain.com/']

# Retrieve a single page and report the URL and contents
def load_url(url, timeout):
    with urllib.request.urlopen(url, timeout=timeout) as conn:
        return conn.read()

# We can use a with statement to ensure threads are cleaned up promptly
with concurrent.futures.ThreadPoolExecutor() as executor:
    # Start the load operations and mark each future with its URL
    future_to_url = {executor.submit(load_url, url, 60): url for url in URLS}
    for future in concurrent.futures.as_completed(future_to_url):
        url = future_to_url[future]
        try:
            data = future.result()
        except Exception as exc:
            print('%r generated an exception: %s' % (url, exc))
        else:
            print('%r page is %d bytes' % (url, len(data)))

import threading
from ibapi.client import EClient
from ibapi.wrapper import EWrapper
from ibapi.contract import Contract
import time


class TestApp(EWrapper, EClient):
    def __init__(self):
        EClient.__init__(self, self)
        self.nextOrderId = 0
        self.permId2ord = {}
        self.strike = 160

    def error(self, reqId, errorCode, errorString):
        print(f&quot;Error: {reqId} {errorCode} {errorString}&quot;)

    def nextValidId(self, orderId: int):
        self.req_data(orderId)

    def req_data(self, orderId):
        optcontract = Contract()
        optcontract.symbol = &quot;AAPL&quot;
        optcontract.secType = &quot;OPT&quot;
        optcontract.exchange = &quot;SMART&quot;
        optcontract.currency = &quot;USD&quot;
        optcontract.lastTradeDateOrContractMonth = &quot;20240419&quot;
        optcontract.strike = self.strike
        optcontract.right = &quot;P&quot;

        self.reqMarketDataType(4)
        self.reqMktData(orderId, optcontract, '106', False, False, [])

    def tickOptionComputation(self, reqId: int, tickType: int, impliedVol,
                              delta, optPrice, pvDividend,
                              gamma, vega, theta, undPrice):
        print(f&quot;Delta: {delta} for option with reqId {reqId}&quot;)
        if delta &gt; 0.22:
            self.strike -= 5
            self.req_data(reqId + 1)
        elif delta &lt; 0.18:
            self.strike += 5
            self.req_data(reqId + 1)
        else:
            print(f&quot;Found an option with Delta in the desired range. Strike: {self.strike} Delta: {delta}&quot;)
            self.cancelMktData(reqId)


def main():
    app = TestApp()
    app.connect('127.0.0.1', 7497, 0)
    app.nextOrderId = 0
    # Call an initial request for OrderId increments
    app.reqIds(-1)
    # Initialize the run loop
    api_thread = threading.Thread(target=lambda: app.run(), daemon=True)
    api_thread.start()

    time.sleep(10)
    app.disconnect()


if __name__ == &quot;__main__&quot;:
    main()

