SCOPES = &quot;read_products,read_orders,read_analytics&quot;

def verify_oauth_request(params: dict, secret: str) -&gt; bool:
    params_without_hmac = params.copy()
    params_without_hmac.pop('hmac', None)
    sorted_params = sorted((k, str(v)) for k, v in params_without_hmac.items())
    query_string = '&amp;'.join(f&quot;{k}={v}&quot; for k, v in sorted_params)
    calculated_hmac = hmac.new(
        secret.encode('utf-8'),
        query_string.encode('utf-8'),
        hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(calculated_hmac, params['hmac'])

@router.get(&quot;/install&quot;)
async def install(shop: str):
    if not shop:
        raise HTTPException(status_code=400, detail=&quot;Shop parameter required&quot;)
    nonce = secrets.token_urlsafe(16)
    install_url = (
        f&quot;https://{shop}/admin/oauth/authorize?&quot;
        f&quot;client_id={SHOPIFY_API_KEY}&amp;&quot;
        f&quot;scope={SCOPES}&amp;&quot;
        f&quot;redirect_uri={REDIRECT_URI}&amp;&quot;
        f&quot;state={nonce}&amp;&quot;
        f&quot;access_mode=offline&quot;
    )
    return RedirectResponse(url=install_url, status_code=307)

