import math

def winning(n, p):
    &quot;&quot;&quot;Find the probability of guessing all balls correct&quot;&quot;&quot;
    a = math.factorial(n)/(math.factorial(n - p) * math.factorial(p))
    b = 1/a
    return b
win = winning(n, p)

