def get_usps_rate(access_token, origin_zip, destination_zip, weight, length, height, width, mail_class):
url = f&quot;{BASE_URL}/shipments/v3/options/search&quot;
headers = {
    &quot;Authorization&quot;: f&quot;Bearer {access_token}&quot;,
    &quot;Content-Type&quot;: &quot;application/json&quot;
}

payload = {
    &quot;pricingOptions&quot;: [
        {
            &quot;priceType&quot;: &quot;RETAIL&quot;
        }
    ],
    &quot;originZIPCode&quot;: origin_zip,
    &quot;destinationZIPCode&quot;: destination_zip,
    &quot;packageDescription&quot;: {
        &quot;weight&quot;: weight,
        &quot;length&quot;: length,
        &quot;height&quot;: height,
        &quot;width&quot;: width,
        &quot;mailClass&quot;: mail_class
    }
}

response = requests.post(url, headers=headers, json=payload)
if response.status_code == 200:
    return response.json()
else:
    print(f&quot;Request payload: {payload}&quot;)
    print(response.status_code)
    print(response.text)
    raise Exception(f&quot;Error fetching USPS rate: {response.json()}&quot;)

def create_post(request):
    form_class = PostForm
    template = 'addpost.html'


    if request.method == &quot;POST&quot;:
        form = form_class(request.POST)
        title = request.POST.get(&quot;title&quot;)
        content = request.POST.get(&quot;content&quot;)
        user_id = request.POST.get(&quot;author&quot;)

        if request.user.has_perm(&quot;posts.add_post&quot;):
            Post.objects.create(
                title=title,
                content=content,
                author=User.objects.get(pk=user_id)
            )
        else:
            pass

    return render(request, template)

def edit_post(request):
    form_class = PostForm
    template = 'editpost.html'

    if request.method == &quot;PATCH&quot;:
        form = form_class(request.PATCH)
        Title = request.PATCH.GET(&quot;title&quot;)
        Content = request.PATCH.GET(&quot;content&quot;)
        User_id = request.PATCH.GET(&quot;author&quot;)

    if request.user.has_perm(&quot;posts.update_post&quot;) and (User_id == User.pk):
        Post.objects.update(
            title=Title,
            content=Content,
            author=User.objects.get(pk=User_id)
        )
    else:
        pass

    return render(request, template)

