def extract_embedded_files_from_docx(self,docx_file):
    &quot;&quot;&quot;
    Extracts embedded files from a DOCX file.
    &quot;&quot;&quot;
    embedded_files = {}

    azure_func = Azure()

    blob_data = azure_func.read_file(
        file_path=docx_file, is_text_content=False
    )

    # Open the DOCX file (which is a ZIP archive)
    with zipfile.ZipFile(BytesIO(blob_data), 'r') as docx_zip:
        # Iterate through files in the DOCX zip to find embedded files
        for file in docx_zip.namelist():
            if file.startswith('word/embeddings/'):
                file_name = os.path.basename(file)
                bin_file_data = docx_zip.read(file)
                # Check if the file is an oleObject*.bin (which could be PDFs or other file types)
                if file_name.startswith('oleObject') and file_name.endswith('.bin'):
                    # Use python-magic to detect the file type

                    mime = magic.Magic(mime=True)
                    file_type = mime.from_buffer(bin_file_data)

                    if file_type == 'application/CDFV2':
                        # Open the CDFV2 (OLE) file using olefile
                        ole = olefile.OleFileIO(BytesIO(bin_file_data))

                        embedded_file_name = self.extract_file_name_from_ole(ole)

                        # List the available storages/streams in the CDFV2 file
                        storages = ole.listdir()
                        print(&quot;Storages in CDFV2 file:&quot;, storages)

                        # Extract from the 'CONTENTS' stream
                        if ['CONTENTS'] in storages:
                                # Extract the file content from the 'CONTENTS' stream
                                file_data = ole.openstream(['CONTENTS']).read()
                                print(f&quot;Extracted content from 'CONTENTS' stream.&quot;)
                        else:
                            # Try extracting data from '\x01Ole' or '\x01Ole10Native'
                            file_data = None
                            for storage in storages:
                                if storage in [['\x01Ole'], ['\x01Ole10Native']]:
                                    print(f&quot;Found embedded file in {storage}. Extracting data...&quot;)
                                    file_data = ole.openstream(storage).read()
                                    break
                                # Use magic to check file type (e.g., PDF, Excel, etc.)
                        embedded_file_type = magic.Magic(mime=True).from_buffer(file_data)

                        if embedded_file_type == 'application/octet-stream':
                            if len(storages) &lt;= 4:
                                image_file_name = file_name.replace('.bin', &quot;.tif&quot;)
                                with open(f&quot;image.tif&quot;, 'wb') as image_file:
                                    image_file.write(bin_file_data)
                                zip_file_name = file_name.replace('.bin', '.zip')
                                with zipfile.ZipFile(zip_file_name, 'w') as zipf:
                                    zipf.write(image_file_name, os.path.basename(image_file_name))
                                file_name=image_file_name.replace('.bin', '.zip')
                                # self.save_file_with_extension(file_data, file_name.replace('.bin', '.zip'))

                        # Determine the correct extension based on MIME type
                        if embedded_file_type == 'application/pdf':
                            file_name=file_name.replace('.bin', '.pdf')
                            # self.save_file_with_extension(file_data, file_name.replace('.bin', '.pdf'))
                        elif embedded_file_type == 'application/zip':
                            file_name=file_name.replace('.bin', '.zip')
                            # self.save_file_with_extension(file_data, file_name.replace('.bin', '.zip'))
                        elif embedded_file_type == 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':
                            file_name=file_name.replace('.bin', '.xlsx')
                            # self.save_file_with_extension(file_data, file_name.replace('.bin', '.xlsx'))
                        elif embedded_file_type == 'application/vnd.ms-excel':
                            file_name=file_name.replace('.bin', '.xlsx')
                            # self.save_file_with_extension(file_data, file_name.replace('.bin', '.xlsx'))
                        elif embedded_file_type == 'application/vnd.openxmlformats-officedocument.wordprocessingml.document':
                            file_name=file_name.replace('.bin', '.docx')
                            # self.save_file_with_extension(file_data, file_name.replace('.bin', '.docx'))
                    else:
                        # If the type is unknown, keep the file name as it is, with .bin extension
                        file_name = file_name.replace('.bin', '.bin')
                    try:
                        embedded_files[file_name] = file_data
                    except:
                        embedded_files[file_name] = bin_file_data

                else:
                    embedded_files[file_name] = bin_file_data

    return embedded_files

import random

MAX_LINES = 3
MAX_BET = 100
MIN_BET = 1

ROWS = 3
COLS = 3

symbol_count = {
    &quot;A&quot;: 2,
    &quot;B&quot;: 4,
    &quot;C&quot;: 6,
    &quot;D&quot;: 8
}

def get_slotmachine_spin(rows, cols, symbols):
    all_symbols = []
    for symbol, symbol_count in symbols.items():
        for _ in range(symbol_count):
            all_symbols.append(symbol)

    columns = []
    for _ in range(cols):
        column = []
        current_symbols = all_symbols[:]
        for _ in range(rows):
            value = random.choice(current_symbols)
            current_symbols.remove(value)
            column.append(value)

        columns.append(column)

    return columns

def print_slot_machine(columns):
    for row in range(len(columns[0])):
        for i, column in enumerate(columns):
            if i != len(columns) - 1:
                print(column[row], end =&quot; | &quot;)
            else:
                print(column[row], end=&quot;&quot;)
        print()

def deposit():
    while True:
        amount = input(&quot;What would you like to deposit? $&quot;)
        if amount.isdigit():
            amount = int(amount)
            if amount &gt; 0:
                break
            else:
                print(&quot;Amount must be greater than 0.&quot;)
        else:
            print(&quot;Please enter a number.&quot;)
    return amount


def get_number_of_lines():
    while True:
        lines = input(&quot;Enter the number of lines to bet on (1-&quot; + str(MAX_LINES) + &quot;)? &quot;)
        if lines.isdigit():
            lines = int(lines)
            if 1 &lt;= MAX_LINES:
                break
            else:
                print(&quot;Enter a valid number of lines.&quot;)
        else:
            print(&quot;Please enter a number.&quot;)
    return lines

def get_bet():
    while True:
        amount = input(&quot;What would you like to bet on each line? $&quot;)
        if amount.isdigit():
            amount = int(amount)
            if MIN_BET &lt;= amount &lt;= MAX_BET:
                break
            else:
                print(f&quot;Amount must be between ${MIN_BET} - ${MAX_BET}.&quot;)
        else:
            print(&quot;Please enter a number.&quot;)
    return amount

def main():
    balance = deposit()
    lines= get_number_of_lines()
    while True:
        bet = get_bet()
        total_bet = bet * lines

        if total_bet &gt;= balance:
            print(f&quot;Insufficient funds. Your current balance is ${balance}.&quot;)
        else:
            break
    print(f&quot;You are betting ${bet} on {lines} lines. Total bet is equal to: ${total_bet}&quot;)

slots = get_slotmachine_spin(ROWS, COLS, symbol_count)
print_slot_machine(slots)

