def first2(s):
    if s[0:1].isalpha():
        return s
    else:
        return False

def length_ok(s):
    if 2&lt;= len (s) &lt;=6:
        return s
    else:
        return False

def punct(s):
    if s in [&quot;.&quot;, &quot; &quot;, &quot;,&quot;]:
        return False


def is_valid(s):
    first2(s)
    length_ok(s)
    punct(s)

