@app.route('/')
def index():
    logging.info(&quot;Index route accessed&quot;)
    if 'access_token' in session:
        return render_template_string('''
            &lt;title&gt;Flask App - Home&lt;/title&gt;
            &lt;h1&gt;Welcome&lt;/h1&gt;
            &lt;p&gt;Access token found in session.&lt;/p&gt;
