from openpyxl.styles import Font
from openpyxl.styles.alignment import Alignment
from openpyxl.styles.borders import Border
from openpyxl.styles.fills import Color
from openpyxl.worksheet.worksheet import Worksheet


def set_cell_style(ws: Worksheet, start_row: int, start_col: int, 
                   end_row: int = None, end_col: int = None,
                   font: Font = None, fill: Color = None, border: Border = None,
                   number_format: str = None, alignment: Alignment = None):
    &quot;&quot;&quot;Applies a new style to a cell or cells&quot;&quot;&quot;
    if not end_row:
        end_row = start_row
    if not end_col:
        end_col = start_col

    for row in range(start_row, end_row + 1):
        for col in range(start_col, end_col + 1):
            if font:
                ws.cell(row = row, column = col).font = font
            if fill:
                ws.cell(row = row, column = col).fill = fill
            if border:
                ws.cell(row = row, column = col).border = border
            if number_format:
                ws.cell(row = row, column = col).number_format = number_format
            if alignment:
                ws.cell(row = row, column = col).alignment = alignment
    return
