class Distance_Loss(nn.Module):
    def __init__(self):
        super(Distance_Loss, self).__init__()
        self.alpha = .6
        self.beta = .4

        self.MSELoss = nn.MSELoss()
    def forward(self, input, target):
        return MSELoss(torch.tensor(distance_transform_edt(input).cpu().numpy()), target)
