# Definition for singly-linked list.
# class ListNode:
#     def __init__(self, val=0, next=None):
#         self.val = val
#         self.next = next
class Solution:
    def mergeKLists(self, lists: List[Optional[ListNode]]) -&gt; Optional[ListNode]:
        if len(lists) == 1:
            return lists[0]
        elif len(lists) == 2:
            return self.merge2Lists(lists[0], lists[1])

        v1 = self.mergeKLists(lists[:len(lists)//2])
        v2 = self.mergeKLists(lists[len(lists)//2:])

        return self.merge2Lists(v1, v2)

    def merge2Lists(self, list1, list2):
        result = ListNode()
        cur = result

        while list1 and list2:
            if list1.val &lt; list2.val:
                cur.next = ListNode(list1.val)
                list1 = list1.next
            else:
                cur.next = ListNode(list2.val)
                list2 = list2.next
            cur = cur.next

        while list1:
            cur.next = ListNode(list1.val)
            list1 = list1.next
            cur = cur.next

        while list2:
            cur.next = ListNode(list2.val)
            list2 = list2.next
            cur = cur.next

        return result.next

