@app.route('/add-user', methods=['POST'])
def addUser():
    current_user = get_user_from_token(request)
    if current_user.admin:
        data = request.get_json()
        username = data.get('username')
        email = data.get('email')
        password = data.get('password')

        if not username or not email or not password:
            return jsonify({&quot;error&quot;: &quot;Tous les champs sont requis.&quot;}), 400

        # Creation de user et account
        try:
            new_user = User(public_id=str(uuid.uuid4()), username=username, password=hash_password(password), email=email,
                            admin=False, two_factor_enabled=False, valid_code=None, valid_code_exp=None,
                            reset_pswd_code=None, reset_pswd_exp=None)
            db.session.add(new_user)
            db.session.commit()
            account_user = Account(user=new_user.id, public_id=str(uuid.uuid4()), balance=0)
            db.session.add(account_user)
            db.session.commit()

            return jsonify({&quot;message&quot;: &quot;Utilisateur ajouté avec succès.&quot;}), 200
        except Exception as e:
            # Capture et affichage de l'erreur
            db.session.rollback()
            return jsonify({'message': f&quot;Une erreur est survenue : {str(e)}&quot;}), 500
    else:
        return jsonify({'message': 'You are not admin'}), 401

from flask import Flask, request, render_template, redirect, url_for
from meta_hidden_interests_extractor import get_hidden_interests

app = Flask(__name__)

@app.route('/', methods=['GET', 'POST'])
def index():
    search_key = request.args.get('search_key', '')
    page = int(request.args.get('page', 1))
    per_page = 100

    if request.method == 'POST':
        search_key = request.form['search_key']
        return redirect(url_for('index', search_key=search_key, page=1))

    if not search_key:
        return render_template('index.html', search_key=search_key, page=page, total_pages=0, data=[])

    data = get_hidden_interests(search_key, page, per_page)

    total_items = len(data)
    total_pages = (total_items // per_page) + (1 if total_items % per_page &gt; 0 else 0)

    return render_template('index.html', data=data, search_key=search_key, page=page, total_pages=total_pages)


if __name__ == '__main__':
    app.run(debug=True, port=5100)
