def longestPalindrome(s: str) -&gt; str:
    aux = 0 
    while True:
        if s[-(aux+1)] not in s[:-(aux+1)]:
            aux+=1
        else:
            break
    s = s if aux == 0 else s[:len(s)-aux]

    longest_palindrome= []
    for idx, value in enumerate(s):
            current = [value]
            if value not in s[idx+1:]:
                continue
            for v in (s[idx+1:]):
                 current.append(v)
                 if current == list(reversed(current)):
                     print('if logic current=', current)
                     longest_palindrome = current if len(longest_palindrome) &lt; len(current) else longest_palindrome
    return longest_palindrome

