def recurse(A, B, step, max_step):
    if A == 1:
        return 1
    if step &gt; max_step:
        return 0
    ways = 0
    if A == 0:
        ways += recurse(1, B, step + 1, max_step)
    if B &gt; 0:
        ways += recurse(A, B - 1, step + 1, max_step)
    if B &lt; 4:
        ways += recurse(A, B + 1, step + 1, max_step)
    return ways

import openai



def parse(narration):
    output = []
    lines = narration.split(&quot;/n&quot;)
    for line in lines:
        if line.startswith('Background: '):
            background = line.replace(&quot;Background:&quot;,&quot;Background: &quot;)
            output.append({
                &quot;type&quot;:&quot;image&quot;,
                &quot;description&quot;:background
            })

        elif line.startswith(&quot;Narration:&quot;):
            text = line.replace(&quot;Narration:&quot;,&quot;Narration:&quot;)
            output.append({
                &quot;type&quot;:&quot;text&quot;,
                &quot;content&quot;:text
            })
    return output


def create(data,output_path=&quot;output_audio.mp3&quot;):
    narration = &quot;&quot;  # Initialize the narration variable as an empty string
    for element in data:
        if element[&quot;type&quot;] != 'text':
            continue
        narration += element[&quot;content&quot;] + &quot;\n\n&quot;
    audio = openai.audio.speech.create(
        model=&quot;tts-1&quot;,
        input = narration,
        voice=&quot;alloy&quot;
    )
    audio.stream_to_file(output_path)




