import requests
import os
from requests.exceptions import RequestException

urls ={'https://upload.wikimedia.org/wikipedia/it/c/c0/2_%E2%82%AC_commemorativo_Italia_2004.png',
       'https://upload.wikimedia.org/wikipedia/it/d/db/2_%E2%82%AC_commemorativo_Austria_2005.png',
       'https://upload.wikimedia.org/wikipedia/it/b/b4/2_%E2%82%AC_commemorativo_Finlandia_2004.jpg',
       'https://upload.wikimedia.org/wikipedia/it/e/ed/2_%E2%82%AC_commemorativo_Belgio_2005.jpg'
}

def scarica(urlImmagini):
    folder = 'Coins'
    os.makedirs(folder, exist_ok=True)

    for indice, urlImmagine in enumerate(urlImmagini, start =1):
        try:
            img_data = requests.get(urlImmagine, allow_redirects=True).content
            ext = urlImmagine.split('.')[-1].lower()
            nome = f&quot;foto_{indice}.{ext}&quot;
            nomeConDir = os.path.join(folder,nome)
            with open(nomeConDir, 'wb') as handler:
                handler.write(img_data)
        except RequestException as e:
            print(f&quot;Errore durante il download dell'immagine {UrlImmagine}: {e}&quot;)

def main():

    scarica(urls)

if __name__ == &quot;__main__&quot;:
    main()

