 class Fifo:

    def __init__(self):
        self._d = {}
        self._cur = 0  # next key to pop

    def __len__(self):
        return len(self._d)

    def append(self, v):
        self._d[self._cur + len(self._d)] = v

    def __next__(self):
        if self._d:
            v = self._d.pop(self._cur)
            self._cur += 1
            return v
        else:
            raise StopIteration

    def __iter__(self):
        return self

class mcast(object):
    def __init__(self):
        self.bufsize = BUFSIZE

    def create(self, MCAST_GROUP, PROTO):
        self.mcast_group = MCAST_GROUP
        self.proto = PROTO
        s = socket(AF_INET, SOCK_RAW, self.proto)
        s.setsockopt(SOL_SOCKET, SO_REUSEADDR, 1)
        s.bind((self.mcast_group, self.proto))
        netinterfaces = getIPAllInterfaces().items()
        for x in range(0, len(netinterfaces)):
            if netinterfaces[x][0] == 'lo':
                continue
            else:
                mcast = inet_aton(self.mcast_group) + inet_aton(netinterfaces[x][1])
                s.setsockopt(IPPROTO_IP, IP_ADD_MEMBERSHIP, str(mcast))
        return s

    def recv(self, s):
        self.s = s
        return self.s.recvfrom(self.bufsize)

