minutes = &quot;0&quot;
seconds = &quot;0&quot;

stopwatch = Stopwatch(2)
stopwatch.stop()


def pause_time():
    pass


def play_time():
    global stopwatch_running, hours, minutes, seconds
    if not stopwatch_running:
        stopwatch.start()
    stopwatch_running = True
    time = str(stopwatch)
    if len(time) &gt; 5:
        seconds = &quot;00&quot;
        minutes = f&quot;00&quot;
        hours = f&quot;00&quot;
    elif len(time) &lt;= 5:
        seconds = f&quot;0{time[-5]}&quot;
        minutes = f&quot;00&quot;
        hours = f&quot;00&quot;
    elif len(time) == 6:
        seconds = f&quot;{time[-6] + time[-5]}&quot;
        minutes = f&quot;00&quot;
        hours = f&quot;00&quot;
    elif len(time) == 8:
        seconds = f&quot;{time[-6] + time[-5]}&quot;
        minutes = f&quot;0{time[-8]}&quot;
        hours = f&quot;00&quot;
    elif len(time) == 9:
        seconds = f&quot;{time[-6] + time[-5]}&quot;
        minutes = f&quot;{time[-9] + time[-8]}&quot;
        hours = f&quot;00&quot;
    elif len(time) == 11:
        seconds = f&quot;{time[-6] + time[-5]}&quot;
        minutes = f&quot;{time[-9] + time[-8]}&quot;
        hours = f&quot;0{time[-11]}&quot;
    elif len(time) == 12:
        seconds = f&quot;{time[-6] + time[-5]}&quot;
        minutes = f&quot;{time[-9] + time[-8]}&quot;
        hours = f&quot;{time[-12] + time[-11]}&quot;
    correct_time = f&quot;{hours}:{minutes}:{seconds}&quot;
    return correct_time


def reset_time():
    pass


def get_frame_count(gif_path):
    with Image.open(gif_path) as im:
        return im.n_frames


