lena_sort(array nums) {
if (nums.size &lt;= 1) {
    return nums;
}
pivot = nums[0];
array less;
array more;
for (i = 1; i &lt; nums.size; ++i) {
    // Comparison
    if (nums[i] &lt; pivot) {
        less.append(nums[i]);
    }
    else {
        more.append(nums[i]);
    }
}
sorted_less = lena_sort(less);
sorted_more = lena_sort(more);
ans = sorted_less + pivot + sorted_more;

return ans;
