class MultiplicatorMixin:

    def multiply(self, m: int) -&gt; int:
        return self.value * m


class AdditionMixin:

    def add(self, b: int) -&gt; int:
        return self.value + b


class MyClass(MultiplicatorMixin, AdditionMixin):

    def __init__(self, value: int) -&gt; None:
        self.value = value


