def format_table(rows):
    formatted = []
    for row in rows:
        if any(row):
            formatted.append(&quot;//&quot;.join(cell.strip() if cell else &quot;&quot; for cell in row))
    return &quot;\n&quot;.join(formatted)

with pdfplumber.open(pdf_path) as pdf, open(output_txt, &quot;w&quot;, encoding=&quot;utf-8&quot;) as output_file:
    for page_number, page in enumerate(pdf.pages, start=1):
        tables = page.extract_tables()
        if tables:
            for table_index, table in enumerate(tables, start=1):
                output_file.write(f&quot;Página {page_number}, Tabla {table_index}:\n&quot;)
                output_file.write(format_table(table))
                output_file.write(&quot;\n\n&quot;)
    print(f&quot;Tablas extraídas y guardadas en '{output_txt}'&quot;)

import pygame

class CameraHandler:
    camera_x, camera_y = 0, 0
    zoom_scale = 1.0

    @staticmethod
    def update_camera_coords(player_rect):
        width, height = pygame.display.get_surface().get_size() 
        CameraHandler.camera_x = min(player_rect.centerx - width // 2, width * 2 - width)
        CameraHandler.camera_y = min(player_rect.centery - height // 2, height * 2 - height)

    def handle_camera_event(event):
        if event.type == pygame.MOUSEWHEEL and pygame.key.get_mods() &amp; pygame.KMOD_CTRL:
            if event.y == 1:
                CameraHandler.zoom_scale = max(CameraHandler.zoom_scale - 0.2, 0.5)
            elif event.y == -1:
                CameraHandler.zoom_scale = min(CameraHandler.zoom_scale + 0.2, 2.5)

    @staticmethod
    def get_camera_surface(sprite_group):
        camera_surface_size = pygame.display.get_surface().get_size()
        camera_surface = pygame.Surface(camera_surface_size, pygame.SRCALPHA)
        camera_surface_size_vector = pygame.math.Vector2(camera_surface_size)
        camera_surface.fill((129, 167, 69))  

        offset_x = -CameraHandler.camera_x
        offset_y = -CameraHandler.camera_y

        for sprite in sprite_group:
            camera_surface.blit(sprite.image, (sprite.rect.x + offset_x, sprite.rect.y + offset_y))

        scaled_surface = pygame.transform.scale(camera_surface, camera_surface_size_vector * CameraHandler.zoom_scale)
        centered_rect = scaled_surface.get_rect(center=(camera_surface_size[0] // 2, camera_surface_size[1] // 2))
        return scaled_surface, centered_rect
     def main(self):
        while self.playing:
            self.events()
            self.update()
            self.draw()
            self.dt = self.clock.tick(self.framerate) / 1000
        self.running = False

    def draw(self):
        camera_surface, rect = CameraHandler.get_camera_surface(self.all_sprites)
        self.screen.blit(camera_surface, rect) 
        pygame.display.update(rect)

def copy_table_statement(table, create_table_columns, cur_to, cur_from):
    &quot;&quot;&quot;
        Create insert table statement if copy data flag is True
    &quot;&quot;&quot;
    table_name_from = table['table_name_from']
    table_name_to = table['table_name_to']
    table_schema = table['table_schema']
    sqlstring = f&quot;SELECT * FROM  {table_schema}.{table_name_from}&quot;

    # copy all data into an insert table statemen
    cur_from.execute(sqlstring)
    table_data = cur_from.fetchall()

    copy_table_sql_statement = F&quot;INSERT INTO {table_schema}.{table_name_to} (&quot;

    column_position = 0
    for column in create_table_columns:
        if (column_position &lt; len(create_table_columns) - 1):
            copy_table_sql_statement = copy_table_sql_statement + &quot; &quot; + column['column_name'] + &quot;, &quot;
        else:
            copy_table_sql_statement = copy_table_sql_statement + &quot; &quot; + column['column_name'] + &quot;) &quot;
        column_position = column_position + 1

    copy_table_sql_statement = copy_table_sql_statement + &quot;VALUES &quot;
    print(copy_table_sql_statement)
    i = 0
    for table_datum in table_data:  
        table_datum_list = list(table_datum)
        j = 0
        for x in table_datum_list:
            if x is None:
                table_datum_list[j] = 'NULL'
            if x == True:
                table_datum_list[j] = 'True'
            if x == False:
                table_datum_list[j] = 'False'
            j = j + 1
        # if table datum is last insert values, end the sql statment with a semi-colon&quot;&quot;&quot;
        print(table_datum_list)
        insert_row = ' '.join(table_datum_list)
        if i &lt; len(table_data) -1:
            copy_table_sql_statement = copy_table_sql_statement + &quot;( &quot; + insert_row + &quot;), &quot;
        else:
            copy_table_sql_statement = copy_table_sql_statement + &quot;( &quot; + insert_row + &quot;);&quot;
        i = i + 1
    return copy_table_sql_statement

