def hoare(arr,start,end):
     pivot = 4
     i,j = start,end
     while i &lt; j:
        while i &lt; j and arr[i] &lt;= pivot:
            i += 1
        while j &gt;= i and arr[j] &gt; pivot:
            j -= 1
        if i &lt; j:
            arr[i],arr[j] = arr[j],arr[i]
     return j
